window.__texto({"id": "690227466", "paragrafos": [{"c": "identifica", "t": "CONSULTA PÚBLICA Nº 7, DE 3 DE MARÇO DE 2026"}, {"c": "ementa", "t": "Proposta de alteração dos Requisitos de Avaliação da Conformidade para Artigos Escolares, aprovados pela Portaria Inmetro nº 423, de 8 de outubro de 2021."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - Inmetro, no exercício da competência que lhe foi outorgada pelos artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos I e IV, da Lei nº 9.933, de 20 de dezembro de 1999, combinados com o disposto no artigo 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, considerando o que consta no Processo SEI nº 0052600.016272/2019-84, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica disponível, no sítio www.inmetro.gov.br, a proposta de texto do aperfeiçoamento dos Requisitos de Avaliação da Conformidade e as Especificações para o Selo de Identificação da Conformidade para Artigos Escolares."}, {"c": "dou-paragraph", "t": "Art. 2º Fica aberto, a partir da data da publicação desta Consulta Pública no Diário Oficial da União, o prazo de 60 (sessenta) dias para que sejam apresentadas sugestões e críticas relativas ao texto proposto."}, {"c": "dou-paragraph", "t": "Art. 3º As críticas e sugestões deverão ser apresentadas na Plataforma Brasil Participativo, contida na página https://brasilparticipativo.presidencia.gov.br."}, {"c": "dou-paragraph", "t": "§ 1º As críticas e sugestões que não forem apresentadas conforme previsto no caput não serão consideradas como válidas para efeito da consulta pública e serão devolvidas ao demandante."}, {"c": "dou-paragraph", "t": "§ 2º O demandante que tiver dificuldade em utilizar a Plataforma poderá solicitar ajuda através dos canais de atendimento do Inmetro, disponíveis na página eletrônica: https://www.gov.br/inmetro/pt-br/canais_atendimento/ouvidoria/faca-sua-manifestacao."}, {"c": "dou-paragraph", "t": "Art. 4º Findo o prazo fixado no art. 2º desta Portaria, o Inmetro se articulará com as entidades que tenham manifestado interesse na matéria, para que indiquem representantes nas discussões posteriores, visando à consolidação do texto final."}, {"c": "dou-paragraph", "t": "Art. 5º Esta Consulta Pública entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "dou-paragraph", "t": "MARCIO ANDRE OLIVEIRA BRITO"}, {"c": "dou-paragraph", "t": "ANEXO I"}, {"c": "dou-paragraph", "t": "PORTARIA Nº xxx, DE xxxx DE xxxx DE 2025"}, {"c": "dou-paragraph", "t": "Altera os Requisitos de Avaliação da Conformidade para Artigos Escolares, aprovados pela Portaria Inmetro nº 423, de 8 de outubro de 2021."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - INMETRO, no exercício da competência que lhe foi outorgada pelos artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos I e IV, da Lei nº 9.933, de 20 de dezembro de 1999, combinado com o disposto no artigo 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, considerando a Consulta Pública nº XX, de XXXXX, de 2025, publicada no DOU de XX, de XXXX, de 2025, página XX, e o que consta no Processo SEI nº 0052600.016272/2019-84, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Ficam excluídos da Portaria Inmetro nº 423, de 2021:"}, {"c": "dou-paragraph", "t": "I - o subitem 6.1.1.4.1.3 do Anexo I;"}, {"c": "dou-paragraph", "t": "II - o subitem 6.1.1.4.1.6 do Anexo I;"}, {"c": "dou-paragraph", "t": "III - o subitem 6.1.1.4.1.7 do Anexo I;"}, {"c": "dou-paragraph", "t": "IV - o subitem 6.1.1.6.3 do Anexo I;"}, {"c": "dou-paragraph", "t": "V - o subitem 6.1.1.6.4 do Anexo I;"}, {"c": "dou-paragraph", "t": "VI - o subitem 6.2.3.1.2 do Anexo I;"}, {"c": "dou-paragraph", "t": "VII - o subitem 6.2.3.2.4.4 do Anexo I;"}, {"c": "dou-paragraph", "t": "VIII - o subitem 6.2.3.2.4.6 do Anexo I;"}, {"c": "dou-paragraph", "t": "IX - o item 3 do Anexo II;"}, {"c": "dou-paragraph", "t": "X - o item 4 do Anexo II;"}, {"c": "dou-paragraph", "t": "Art. 2º A Portaria Inmetro nº 423, de 2021, passa a vigorar com as seguintes alterações:"}, {"c": "dou-paragraph", "t": "\"Art. 7º ....................................................."}, {"c": "dou-paragraph", "t": "§ 1º .........................................................."}, {"c": "dou-paragraph", "t": "§ 2 º ........................................................."}, {"c": "dou-paragraph", "t": "§ 3 º Os artigos escolares certificados na forma de kit escolar, conforme definido no Anexo I desta Portaria, devem ser tratados conforme estabelecido no RGCP vigente.\""}, {"c": "dou-paragraph", "t": "......................................................"}, {"c": "dou-paragraph", "t": "\"Art.13.A Os processos certificação deverão ser adequados às disposições da Portaria definitiva resultante da Consulta Pública nº XX, de XXXX, de XXXXXX, na etapa de manutenção ou recertificação imediatas à sua publicação, desde que não ocorram em prazo inferior a 12 (doze) meses, quando poderá ser utilizada a etapa subsequente de avaliação."}, {"c": "dou-paragraph", "t": "§ 1º Os certificados vigentes deverão ter sua validade ajustada para 6 (seis) anos, nos termos do estabelecido no Anexo I desta Portaria, tendo por referência a sua data de concessão."}, {"c": "dou-paragraph", "t": "§ 2º Os processos de concessão inicial de certificação deverão ser adequados às disposições da Portaria definitiva resultante da Consulta Pública nº XX, de XXXX, de XXXXXX no prazo de 3 (três) meses contados de sua publicação. \" (NR)"}, {"c": "dou-paragraph", "t": "................................................"}, {"c": "dou-paragraph", "t": "ANEXO I"}, {"c": "dou-paragraph", "t": "................................................"}, {"c": "dou-paragraph", "t": "\"4.1 Artigo Escolar"}, {"c": "dou-paragraph", "t": "Qualquer objeto ou material, podendo ser produzido com motivos infantis ou personagens infantis, projetado para uso por crianças menores de 14 anos, com ou sem funcionalidade lúdica, a ser utilizado no ambiente escolar e/ou em atividades educativas."}, {"c": "dou-paragraph", "t": "4.2 Apagável"}, {"c": "dou-paragraph", "t": "Característica de um objeto ou material formador de traço para escrita ou desenho, com tinta que seja facilmente apagável pelo usuário, utilizando para tanto por exemplo borracha comum ou fricção, apresentando, geralmente, a informação \"apagável\", de forma clara e em língua portuguesa, na embalagem do produto.\" (NR)"}, {"c": "dou-paragraph", "t": "..............................................."}, {"c": "dou-paragraph", "t": "\"4.5 Família"}, {"c": "dou-paragraph", "t": "Agrupamento de modelos de artigos escolares produzidos por mesmo fabricante, na mesma unidade fabril, que apresentem mesmo processo produtivo, mesmo material base e mesma destinação de uso, obedecendo ao estabelecido no Anexo A."}, {"c": "dou-paragraph", "t": "4.6 Motivo infantil"}, {"c": "dou-paragraph", "t": "Elemento decorativo ou figurativo, isolado ou repetido em padrões, projetado especificamente para atrair crianças. Pode incluir elementos visuais ou designs relacionados ao universo infantil. Isso inclui temas como animais, brinquedos, objetos lúdicos (como balões, carrinhos, bonecas, etc) e qualquer ilustração que remeta ao imaginário e ao cotidiano das crianças."}, {"c": "dou-paragraph", "t": "Nota: Os motivos infantis são caracterizados por cores vibrantes, traços simples e formas que despertam a curiosidade e diversão no público infantil.\" (NR)"}, {"c": "dou-paragraph", "t": "................................................"}, {"c": "dou-paragraph", "t": "\"4.8 Personagem infantil"}, {"c": "dou-paragraph", "t": "Figuras, muitas vezes inspiradas em desenhos animados, contos, histórias em quadrinhos, livros infantis ou filmes infantis, que têm grande apelo junto às crianças."}, {"c": "dou-paragraph", "t": "Nota: Exemplos comuns incluem heróis, princesas, animais com características humanizadas (como os de desenhos animados) e personagens de séries ou filmes direcionados ao público infantil. Esses personagens são reconhecíveis e frequentemente têm características positivas e educativas, como coragem, amizade e diversão.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.1.1 Solicitação de Certificação"}, {"c": "dou-paragraph", "t": "O fornecedor deve encaminhar uma solicitação formal ao OCP, fornecendo a documentação descrita no RGCP, complementado pelo memorial descritivo, que deve ser elaborado de acordo com o estabelecido no Anexo B.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.1.3 Auditoria Inicial do Sistema de Gestão da Qualidade e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "6.1.1.3.1 Os critérios de auditoria do Sistema de Gestão da Qualidade devem seguir os requisitos estabelecidos no RGCP, além das disposições a seguir."}, {"c": "dou-paragraph", "t": "6.1.1.3.2 As avaliações dos subitens 8.4.2, 8.4.3 e 8.6 das Tabela 2 e 3 do RGCP devem ser focadas, em particular, em materiais que possam ser tóxicos ou apresentar metais pesados (Exemplos: tintas, adesivos, etiquetas e acessórios do artigo escolar). Deve ser evidenciado procedimento para inspeção de recebimento da matéria prima, bem como registros dos resultados de ensaios."}, {"c": "dou-paragraph", "t": "6.1.1.3.3 As avaliações dos subitens 8.5.1 e 8.5.5 das Tabelas 2 e 3 do RGCP devem ser focadas em parâmetros operacionais das máquinas (Exemplos: ciclo, temperatura, 25pressão e controle de massa processada, uso de material moído reprocessado, remoção de rebarbas e operações de acabamento do artigo escolar) visando garantir ausência de bordas afiadas nas peças produzidas. As avaliações também devem focar processos de colagem, soldas, encaixe de componentes, utilização de ímãs, bem como a fixação de componentes como pinos ou outros acessórios do artigo escolar."}, {"c": "dou-paragraph", "t": "6.1.1.3.4 Nas avaliações do subitem 8.5.2 das Tabelas 2 e 3 do RGCP, deve ser constatado se o fabricante possui um sistema de rastreabilidade que permita relacionar o artigo escolar certificado com a fábrica em que foi efetivamente produzido, contemplando necessariamente a data de fabricação e o lote de fabricação do artigo escolar. Deve-se também apresentar o código de barras."}, {"c": "dou-paragraph", "t": "6.1.1.3.5 Deve ser evidenciado procedimento do subitem 8.6 das Tabelas 2 e 3 do RGCP, bem como registros dos resultados de ensaios."}, {"c": "dou-paragraph", "t": "6.1.1.3.6 Deve ser evidenciado procedimento do subitem 8.6 das Tabelas 2 e 3 do RGCP, bem como registros dos resultados de ensaios.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.1.4.1.4 Para artigos escolares que contém tinta, cola, guache, aquarela e material em pó em quantidade de massa superior a 3g por unidade de uso, deverá ser cumprido, quanto aos ensaios toxicológicos, o estabelecido na norma ABNT NBR 15236:2021."}, {"c": "dou-paragraph", "t": "6.1.1.4.1.5 Para a certificação inicial ou recertificação, deverá ser realizado o ensaio de caracterização da substância analisada, para o(s) modelo(s) representante(s) da família, através de espectrometria FTIR, conforme metodologia estabelecida na norma ABNT NBR 15236:2021. Durante o mesmo ciclo de certificação, os resultados desses ensaios de espectrometria FTIR servirão de base para futuras comparações, quando das manutenções da certificação.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.1.4.1.8 ..................................................."}, {"c": "dou-paragraph", "t": "a) razão social/nome fantasia e endereço do fabricante ou importador;"}, {"c": "dou-paragraph", "t": "b) prazo de validade do artigo escolar, quando for aplicável;"}, {"c": "dou-paragraph", "t": "c) composição do material (aplicável quando o artigo escolar for composto por material líquido, pó, pasta ou gel); e"}, {"c": "dou-paragraph", "t": "d) informações e símbolos de restrição de faixa etária, quando for aplicável.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "Tabela 3 - Plano de amostragem e fragmentação das amostras para ensaios (Modelo 5)"}, {"c": "", "t": "Artigo Escolar"}, {"c": "", "t": "Quantidade (unidades)"}, {"c": "", "t": "Ensaios para todos os produtos"}, {"c": "", "t": "Ensaios que dependem do tipo de produto"}, {"c": "", "t": "Químico"}, {"c": "", "t": "Propriedades Gerais, Mecânicas e Físicas"}, {"c": "", "t": "Elétrico"}, {"c": "", "t": "Ftalatos"}, {"c": "", "t": "Microbiológico"}, {"c": "", "t": "Toxicológico"}, {"c": "", "t": "FTIR"}, {"c": "", "t": "Quantidade para cada tipo de ensaio (unidades)"}, {"c": "", "t": "Apontador"}, {"c": "", "t": "24"}, {"c": "", "t": "10"}, {"c": "", "t": "4"}, {"c": "", "t": "10"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "Borracha e Ponteira de borracha"}, {"c": "", "t": "30"}, {"c": "", "t": "6"}, {"c": "", "t": "4"}, {"c": "", "t": "Para o ensaio elétrico, se necessário, será realizada coleta de 1 (uma) unidade do artigo escolar representante de cada família, sendo esta unidade retirada da amostra destinada aos ensaios de propriedades gerais, mecânicas e físicas."}, {"c": "", "t": "20"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "Canetaesferográfica/roller/gelCaneta hidrográfica (hidrocor)Marcador de texto"}, {"c": "", "t": "53"}, {"c": "", "t": "10"}, {"c": "", "t": "4"}, {"c": "", "t": "26"}, {"c": "", "t": "5"}, {"c": "", "t": "5"}, {"c": "", "t": "3"}, {"c": "", "t": "Giz de ceraLápis (preto ou grafite)Lápis de corLapiseira"}, {"c": "", "t": "40"}, {"c": "", "t": "10"}, {"c": "", "t": "4"}, {"c": "", "t": "26"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "Cola (líquida ou sólida)"}, {"c": "", "t": "43"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "5"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "3"}, {"c": "", "t": "Corretor Adesivo"}, {"c": "", "t": "14"}, {"c": "", "t": "5"}, {"c": "", "t": "4"}, {"c": "", "t": "5"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "Corretor em Tinta"}, {"c": "", "t": "43"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "5"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "3"}, {"c": "", "t": "Compasso Curva francesa Esquadro Normógrafo RéguaTransferidor"}, {"c": "", "t": "10"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "3"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "Massa plástica"}, {"c": "", "t": "16"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "3"}, {"c": "", "t": "NA"}, {"c": "", "t": "3"}, {"c": "", "t": "3"}, {"c": "", "t": "Pasta com aba elástica"}, {"c": "", "t": "10"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "3"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "Tesoura de ponta redonda"}, {"c": "", "t": "10"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "3"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "NA"}, {"c": "", "t": "Tinta (guache, nanquim, pintura a dedo, plástica, aquarela)"}, {"c": "", "t": "43"}, {"c": "", "t": "3"}, {"c": "", "t": "4"}, {"c": "", "t": "5"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "3"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.1.4.2.4 Em caso de reprovação no ensaio de prova, os ensaios devem ser repetidos para o atributo não conforme em novas amostras (contraprova e testemunha), tendo como base os critérios estabelecidos neste RAC.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.1.6.2 O Certificado de Conformidade deve ter validade de 06 (seis) anos a partir de sua emissão.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"Quadro 1 - Instrução de notação do(s) modelo(s) da família no Certificado de Conformidade"}, {"c": "", "t": "Marca"}, {"c": "", "t": "Modelo(Designação comercial do modelo e códigos de referência comercial, de todas as versões, se existentes)."}, {"c": "", "t": "Descrição(Descrição técnica do modelo)- dimensões, volume ou unidades- decoração, tema ou cores"}, {"c": "", "t": "Código de barras comercial(Para todas as versões do modelo, quando existente)."}, {"c": "dou-paragraph", "t": ".. \" (NR)"}, {"c": "dou-paragraph", "t": "\"6.1.1.6.5.2 No certificado, as famílias devem ser nomeadas contendo o nome da família do artigo escolar conforme Anexo A deste RAC, seguida do(s) material(is) base."}, {"c": "dou-paragraph", "t": "6.1.1.6.5.2.1 A seguir, exemplos de nomeação das famílias no certificado:"}, {"c": "dou-paragraph", "t": "- Caneta esferográfica/polipropileno,tinta;"}, {"c": "dou-paragraph", "t": "- Lápis de cor/madeira,mina;"}, {"c": "dou-paragraph", "t": "- Lápis grafite/madeira,grafite. \" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.2.1.2 A auditoria de manutenção deve ser realizada e concluída 1 (uma) vez a cada período de 24 (vinte e quatro) meses, contados a partir da data de emissão do certificado de conformidade."}, {"c": "dou-paragraph", "t": "6.1.2.2 Plano de Ensaios de Manutenção"}, {"c": "dou-paragraph", "t": "Os critérios do Plano de Ensaios de Manutenção devem seguir o estabelecido no RGCP. Os ensaios de manutenção devem ser realizados e concluídos 1 (uma) vez a cada período de 24 (vinte e quatro) meses, contados a partir da emissão do certificado de conformidade.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.2.2.1.1 Na manutenção da certificação, para fins de comprovação da não alteração das propriedades da substância inicialmente ensaiada nos ensaios de irritação dérmica primária e toxicidade aguda oral realizados na etapa inicial, deve ser realizado ensaio para o(s) pais(s) da família, através da espectrometria FTIR, conforme metodologia estabelecida na norma ABNT NBR 15236:2021."}, {"c": "dou-paragraph", "t": "6.1.2.2.1.2 Caberá ao OCP, para a realização dos ensaios de manutenção através da espectrometria FTIR, selecionar o(s) mesmo(s) pais(s) da família do artigo escolar ensaiado no ensaio inicial ou de recertificação.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.2.2.1.5 Caso o perfil espectrométrico analisado na manutenção corresponda ao perfil obtido na avaliação inicial ou de recertificação, o fornecedor ficará dispensado de realizar os ensaios de irritabilidade dérmica e intoxicação oral aguda na etapa de manutenção.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.1.3.2 A avaliação de recertificação deve ser realizada a cada 06 (seis) anos, devendo ser concluída antes do vencimento do prazo de validade do Certificado de Conformidade.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.2.3.1.1 Os ensaios devem seguir o definido do RGCP, seguindo o estabelecido no subitem 6.1.1.4.1.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"Tabela 5 - Plano de Amostragem e Fragmentação das Amostras para o Modelo 1b"}, {"c": "", "t": "Tamanho do lote de certificação da família"}, {"c": "", "t": "Quantidade total amostrada (em unidades)"}, {"c": "", "t": "Ensaios para todos os produtos"}, {"c": "", "t": "Ensaios que dependem do tipo de produto"}, {"c": "", "t": "Químico"}, {"c": "", "t": "Propriedades gerais, mecânicas e físicas"}, {"c": "", "t": "Elétrico"}, {"c": "", "t": "Ftalato"}, {"c": "", "t": "Microbiológico"}, {"c": "", "t": "Toxicológico"}, {"c": "", "t": "Quantidade mínima de amostras para cada ensaio (em unidades)"}, {"c": "", "t": "Inferior a 10000"}, {"c": "", "t": "110"}, {"c": "", "t": "16"}, {"c": "", "t": "40"}, {"c": "", "t": "Quando necessário será realizado este ensaio para cada faixa do lote, nas mesmas amostras que foram ensaiadas nos ensaios de Propriedades físicas, gerais e mecânica."}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "10001 a 25000"}, {"c": "", "t": "130"}, {"c": "", "t": "16"}, {"c": "", "t": "60"}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "25001 a 50000"}, {"c": "", "t": "150"}, {"c": "", "t": "16"}, {"c": "", "t": "80"}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "50001 a 100000"}, {"c": "", "t": "170"}, {"c": "", "t": "16"}, {"c": "", "t": "100"}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "100001 a 200000"}, {"c": "", "t": "190"}, {"c": "", "t": "16"}, {"c": "", "t": "120"}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "200001 a 400000"}, {"c": "", "t": "210"}, {"c": "", "t": "16"}, {"c": "", "t": "140"}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "400001 a 800000"}, {"c": "", "t": "230"}, {"c": "", "t": "16"}, {"c": "", "t": "160"}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "800000 a 1000000"}, {"c": "", "t": "250"}, {"c": "", "t": "16"}, {"c": "", "t": "180"}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "", "t": "Acima de 1000000"}, {"c": "", "t": "270"}, {"c": "", "t": "16"}, {"c": "", "t": "200"}, {"c": "", "t": "26"}, {"c": "", "t": "25"}, {"c": "", "t": "3"}, {"c": "dou-paragraph", "t": "\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.2.3.2.4.3 A amostragem especificada na Tabela 5, referente aos ensaios químicos, ftalatos, microbiológicos e toxicológicos, não varia em função do tamanho do lote de certificação.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.2.3.2.4.5 A amostragem especificada na Tabela 5 para os ensaios de propriedades gerais, mecânicas e físicas é referente a todas as unidades necessárias para os ensaios previstos na norma ABNT NBR 15236:2021.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"6.2.3.2.4.7 Todas as amostras ensaiadas devem ser aprovadas em todos os ensaios realizados.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "ANEXO A"}, {"c": "dou-paragraph", "t": "........................................................"}, {"c": "dou-paragraph", "t": "\"1.1. ..................................................."}, {"c": "dou-paragraph", "t": "a) produzidos por um mesmo fabricante e mesma unidade fabril;"}, {"c": "dou-paragraph", "t": "b) apresentam a mesma destinação de uso."}, {"c": "dou-paragraph", "t": "b.1) a família poderá estar composta por produtos que não apresentem peças de mesmo tamanho, mas que estejam dirigidas a uma mesma destinação de uso, com as mesmas finalidades (neste caso, as peças devem apresentar estruturas iguais e serem produzidas com o mesmo processo de fabricação e o mesmo material base);"}, {"c": "dou-paragraph", "t": "c) requerem o mesmo tipo de ensaio (E) da norma de referência, conforme classificação a seguir:"}, {"c": "dou-paragraph", "t": "E 1 - físicos e mecânicos"}, {"c": "dou-paragraph", "t": "E 2 - químicos - migração de certos elementos"}, {"c": "dou-paragraph", "t": "E 3 - pentaclorofenol e seus sais"}, {"c": "dou-paragraph", "t": "E 4 - ftalatos"}, {"c": "dou-paragraph", "t": "E 5 - toxicidade aguda oral e dérmica"}, {"c": "dou-paragraph", "t": "E 6 - ensaios de contaminação microbiológica"}, {"c": "dou-paragraph", "t": "d) são fabricados no mesmo material base (M), conforme classificação a seguir:"}, {"c": "dou-paragraph", "t": "M 01 - termoplástico rígido, termoplástico expandido"}, {"c": "dou-paragraph", "t": "M 02 - plástico flexível exceto PVC (exemplo: EVA)"}, {"c": "dou-paragraph", "t": "M 03 - plástico PVC"}, {"c": "dou-paragraph", "t": "M 04 - papel, papelão, pintado, metalizado, crepom, laminado plástico (exceto PVC) simples ou aplicado em papel"}, {"c": "dou-paragraph", "t": "M 05 - tinta base água, tinta plástica, tinta guache, cola base água;"}, {"c": "dou-paragraph", "t": "M 06 - tinta base solvente, nanquim, cola base solvente"}, {"c": "dou-paragraph", "t": "M 07 - elastômeros termoplásticos, borracha, látex"}, {"c": "dou-paragraph", "t": "M 08 - madeira natural, compensado, aglomerado, mdf"}, {"c": "dou-paragraph", "t": "M 09 - cera, parafina, massa plástica, cola sólida (bastão), minas de lápis de cor"}, {"c": "dou-paragraph", "t": "M 10 -grafite"}, {"c": "dou-paragraph", "t": "M 11 - metais"}, {"c": "dou-paragraph", "t": "M 12 - material em pó, pasta ou gel"}, {"c": "dou-paragraph", "t": "Nota: Entende-se como material base, o material principal do artigo escolar, não influenciando acessórios, decoração, tamanhos, volumes ou quantidades. Exemplo: lápis grafite de 24 unidades ou 12 unidades, canetas que variam as cores da tinta, colas que variam entre 40 ml e 80 ml.\" NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"2.1 Cabe ao OCP registrar para cada família o artigo escolar identificado como pai da família, e os demais artigos escolares que compõe a família. Este registro deve conter, além da descrição dos artigos escolares, fotos dos mesmos (esta foto pode ser mantida em arquivo magnético)."}, {"c": "dou-paragraph", "t": "2.2 Deve ser apresentada ao OCP pelo menos uma amostra, fotografia e catálogos de cada um dos modelos componentes da mesma família objeto da certificação, para a análise de seus aspectos específicos e escolha do pai da família."}, {"c": "dou-paragraph", "t": "2.3 O pai da família será o(s) produto(s) que apresente(m) maior número de requisitos de ensaio exigíveis pelas normas aplicáveis quanto à segurança. Ou seja, em uma família de artigos escolares, o pai da família é o artigo escolar mais completo, com maior número de itens de ensaio, com tinta de pigmentação mais forte, ou outros atributos que demandem maior risco. Portanto, características como cor, decoração, quantidade, desenho, dimensão não configuram nova família, mas servem de base na escolha do pai da família."}, {"c": "dou-paragraph", "t": "Exemplos:"}, {"c": "dou-paragraph", "t": "Família 1: lápis de cor de 24 cores e 12 cores, o pai da família será o lápis de cor de 24 cores."}, {"c": "dou-paragraph", "t": "Família 2: Borrachas com ou sem capa plástica, o pai da família será a borracha com capa plástica."}, {"c": "dou-paragraph", "t": "Família 3: marca texto, de tamanhos diferentes, o pai da família é o marca-texto de menor tamanho."}, {"c": "dou-paragraph", "t": "Família 4: caneta com ou sem grip, o pai da família será a caneta com grip."}, {"c": "dou-paragraph", "t": "2.4 Para família de até 10 modelos, será considerado apenas um pai de família. No caso de mais de dez modelos por família, o(s) modelo(s) de artigo(s) escolar(es) considerado pai da família será representado por 10% do número de diferentes modelos da mesma família, arredondados para o número inteiro imediatamente superior."}, {"c": "dou-paragraph", "t": "Exemplo: em uma família composta por 95 modelos diferentes de Artigos Escolares, o pai é o conjunto de 10 (1) modelos (10%), escolhidos de acordo com o critério do subitem 2.1 deste Anexo, dentre os 100 modelos considerados da mesma família.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "ANEXO B"}, {"c": "dou-paragraph", "t": "\"1. ..................................................."}, {"c": "dou-paragraph", "t": "d) nome comercial do produto e códigos de referência comercial, se houver;"}, {"c": "dou-paragraph", "t": ".................................................."}, {"c": "dou-paragraph", "t": "n) nome do responsável pelo preenchimento das informações.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "ANEXO C"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "", "t": "\"Faixa Etária"}, {"c": "", "t": "Artigo Escolar"}, {"c": "", "t": "Fase da Criança"}, {"c": "", "t": "Acima de 3 anos"}, {"c": "", "t": "- Borracha- Caneta hidrográfica (hidrocor)- Cola (líquida ou sólida)- Giz de cera"}, {"c": "", "t": "Criança com probabilidade de ações provenientes da idade oral.Há relativa coordenação motora, com baixa noção de perigo, e a criança possui percepção global, mas sem discriminar detalhes."}, {"c": "", "t": "- Lápis (grafite ou de cor)- Massa Plástica- Pasta aba e elástica- Tinta (guache, pintura a dedo, plástica)"}, {"c": "", "t": "Acima de 4 anos"}, {"c": "", "t": "- Apontador- Tesoura de ponta redonda"}, {"c": "", "t": "Criança com probabilidade de ações provenientes da idade oral.Há relativa coordenação motora, com baixa noção de perigo, e a criança possui percepção global, mas sem discriminar detalhes."}, {"c": "", "t": "Acima de 6 anos"}, {"c": "", "t": "- Caneta esferográfica roller ou gel- Compasso, transferidor, normógrafo, curva francesa- Corretor (adesivo ou em tinta)"}, {"c": "", "t": "Criança diminui probabilidade de ações da idade oral, com coordenação motora baseada na reversibilidade e completamente desenvolvida a partir dos 8 anos, noção de perigo, com percepção global, discriminando detalhes."}, {"c": "", "t": "- Esquadro- Lapiseira- Marcador de texto- Régua"}, {"c": "dou-paragraph", "t": "\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "ANEXO II"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"Tabela 1 - Formas de aplicação do Selo de Identificação da Conformidade"}, {"c": "", "t": "Artigo Escolar"}, {"c": "", "t": "Forma de Aplicação"}, {"c": "", "t": "- Apontador- Borracha- Caneta esferográfica, roller ou gel- Caneta hidrográfica (hidrocor)- Cola (líquida ou sólida)"}, {"c": "", "t": "a) Produtos comercializados no ponto de venda sem embalagem (a granel):O Selo de Identificação da Conformidade deve ser aposto na embalagem expositora, de forma clara, gravado (em forma de adesivo ou não), em baixo ou em alto relevo, conforme estabelecido na Figura 1 do presente Anexo. Nestes casos, o produto deve conter marcações que possibilitem sua rastreabilidade à respectiva embalagem expositora, devendo a mesma estar disponível no ponto de venda."}, {"c": "", "t": "- Compasso- Corretor (adesivo ou tinta)- Curva francesa- Giz de cera;- Lápis de cor"}, {"c": "", "t": "Embalagem Expositora: Selo Completo, observado o disposto na Nota da Figura 1 do presente Anexo.b) Produtos comercializados no ponto de venda com embalagem:"}, {"c": "", "t": "O Selo de Identificação da Conformidade deve ser aposto na embalagem do produto, de forma clara, gravado (em forma de adesivo ou não), em baixo ou em alto relevo, conforme estabelecido na Figura 1 do presente Anexo.Embalagem do Produto: Selo Completo, observado o disposto na Nota da Figura 1 do presente Anexo."}, {"c": "", "t": "- Lápis preto ou grafite- Lapiseira- Massa plástica- Marcador de texto- Normógrafo"}, {"c": "", "t": "- Régua- Tesoura de ponta redonda- Tinta (guache, plástica, pintura a dedo)"}, {"c": "", "t": "- Pasta com aba elástica"}, {"c": "", "t": "O Selo de Identificação da Conformidade deve ser aposto no corpo do produto e na embalagem do produto, de forma clara, gravado (em forma de adesivo ou não), em baixo ou em alto relevo, ou costurado, conforme estabelecido na Figura 1 do presente Anexo.Produto: Selo Completo ou Compacto.Embalagem do Produto: Selo Completo, observado o disposto na Nota da Figura 1 do presente Anexo."}, {"c": "", "t": "- Esquadro- Transferidor"}, {"c": "", "t": "a) Produtos comercializados no ponto de venda sem embalagem:O Selo de Identificação da Conformidade deve ser aposto no corpo do produto, de forma clara, gravado (em forma de adesivo ou não), em baixo ou em alto relevo, conforme estabelecido na Figura 1 do presente Anexo.Produto: Selo Completo ou Compacto."}, {"c": "", "t": "b) Produtos comercializados no ponto de venda com embalagem:O Selo de Identificação da Conformidade deve ser aposto na embalagem do produto, de forma clara, gravado (em forma de adesivo ou não), em baixo ou em alto relevo, conforme estabelecido na Figura 1 do presente Anexo.Embalagem do Produto: Selo Completo."}, {"c": "dou-paragraph", "t": "\" (NR)"}, {"c": "dou-paragraph", "t": ".............................................................................."}, {"c": "dou-paragraph", "t": "\"3. Os artigos escolares contemplados neste RAC, mesmo quando ofertados como brindes, devem ostentar o Selo de Identificação da Conformidade."}, {"c": "dou-paragraph", "t": "3.1 Produtos que contêm artigos escolares como brindes não podem exibir o Selo de Identificação da Conformidade na sua embalagem, mas sim no artigo escolar e/ou na embalagem do artigo escolar ofertado como brinde."}, {"c": "dou-paragraph", "t": "3.2 A embalagem do produto que contém o artigo escolar ofertado como brinde deve apresentar os seguintes dizeres:"}, {"c": "dou-paragraph", "t": "ATENÇÃO: Contém artigo escolar certificado no âmbito do Sistema Brasileiro de Avaliação da Conformidade.\" (NR)"}, {"c": "dou-paragraph", "t": "..................................................."}, {"c": "dou-paragraph", "t": "\"ANEXO III - ENQUADRAMENTO TÉCNICO DE ARTIGOS ESCOLARES"}, {"c": "dou-paragraph", "t": "A seguir são apresentadas definições técnicas detalhadas dos artigos escolares abrangidos por este Regulamento, especificando claramente seus escopos e suas respectivas exceções:"}, {"c": "dou-paragraph", "t": "1. Apontador"}, {"c": "dou-paragraph", "t": "1.1 Escopo:"}, {"c": "dou-paragraph", "t": "Objeto utilizado para apontar lápis de acionamento manual, com orifício de diâmetro de até 10 mm para inserção do lápis, podendo apresentar qualquer formato ou material."}, {"c": "dou-paragraph", "t": "1.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produtos que apresentem uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Apontadores com orifício de diâmetro superior a 10 mm para inserção do lápis;"}, {"c": "dou-paragraph", "t": "- Apontadores motorizados ou acionados por manivela;"}, {"c": "dou-paragraph", "t": "- Apontadores exclusivos para minas;"}, {"c": "dou-paragraph", "t": "- Apontadores destinados a cosméticos (lápis de olho, batom, sombra), desde que claramente identificados de forma clara, precisa, ostensiva e em língua portuguesa na embalagem."}, {"c": "dou-paragraph", "t": "2. Borracha"}, {"c": "dou-paragraph", "t": "2.1 Escopo:"}, {"c": "dou-paragraph", "t": "Objeto usado para apagar a escrita ou o desenho, que apresente todas as características a seguir:"}, {"c": "dou-paragraph", "t": "- Borracha branca ou colorida;"}, {"c": "dou-paragraph", "t": "- Borracha em qualquer formato ou material;"}, {"c": "dou-paragraph", "t": "- Borracha que contenha ou não uma cavidade interna para encaixe em instrumentos formadores de traço."}, {"c": "dou-paragraph", "t": "2.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Caneta-borracha fabricada em qualquer material, com refil de borracha;"}, {"c": "dou-paragraph", "t": "- Caneta-borracha fabricada em qualquer material, sem refil de borracha;"}, {"c": "dou-paragraph", "t": "- Refil de borracha para ser usado em caneta-borracha;"}, {"c": "dou-paragraph", "t": "- Borracha motorizada ou elétrica;"}, {"c": "dou-paragraph", "t": "- Lápis-borracha, fabricado em qualquer material, que necessite ser apontado para possibilitar o uso da borracha;"}, {"c": "dou-paragraph", "t": "- Borracha limpa-tipos, também denominada borracha maleável ou borracha de amassar, utilizada para desenho técnico com função de suavizar traços de desenho em grafite, pastel ou carvão."}, {"c": "dou-paragraph", "t": "3. Caneta Esferográfica, Roller ou Gel"}, {"c": "dou-paragraph", "t": "3.1 Escopo:"}, {"c": "dou-paragraph", "t": "Caneta esferográfica, roller ou gel, formadora de traço para escrita, que apresente todas as características a seguir:"}, {"c": "dou-paragraph", "t": "- Tinta não apagável;"}, {"c": "dou-paragraph", "t": "- Mecanismo de liberação da tinta que utilize esfera, produzida em qualquer material;"}, {"c": "dou-paragraph", "t": "- Reservatório da tinta manufaturado em polímero (resina termoplástica);"}, {"c": "dou-paragraph", "t": "- Corpo manufaturado em polímero (resina termoplástica)."}, {"c": "dou-paragraph", "t": "3.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Corpo manufaturado em material diferente de polímero (resina termoplástica);"}, {"c": "dou-paragraph", "t": "- Reservatório da tinta manufaturado em material diferente de polímero (resina termoplástica);"}, {"c": "dou-paragraph", "t": "- Mecanismo de liberação da tinta que não utilize esfera;"}, {"c": "dou-paragraph", "t": "- Tinta apagável, desde que descrito de forma clara, precisa, ostensiva e em língua portuguesa na embalagem."}, {"c": "dou-paragraph", "t": "4. Caneta Hidrográfica (Hidrocor)"}, {"c": "dou-paragraph", "t": "4.1 Escopo:"}, {"c": "dou-paragraph", "t": "- Caneta hidrográfica (hidrocor), formador de traço para escrita ou desenho, apagável, ou não apagável, podendo ou não ser lavável; que apresente todas as características a seguir:"}, {"c": "dou-paragraph", "t": "- Corpo manufaturado em polímero (resina termoplástica);"}, {"c": "dou-paragraph", "t": "- Tinta à base água, desde que descrita a base da tinta de forma clara, precisa, ostensiva e em língua portuguesa na embalagem;"}, {"c": "dou-paragraph", "t": "- Sistema de liberação da tinta que utiliza uma ponta fibrosa, rígida, podendo apresentar qualquer material para a fixação desta ponta."}, {"c": "dou-paragraph", "t": "4.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Corpo manufaturado em material diferente da resina termoplástica;"}, {"c": "dou-paragraph", "t": "- Tinta que não seja à base de água (canetas não hidrográficas), desde que descrita a base da tinta de forma clara, precisa, ostensiva e em língua portuguesa na sua embalagem;"}, {"c": "dou-paragraph", "t": "- Ponta fibrosa flexível (exemplo: caneta pincel, brush, lettering) desde que evidenciado de forma clara, precisa, ostensiva e em língua portuguesa na embalagem;"}, {"c": "dou-paragraph", "t": "- Marcador permanente de objetos;"}, {"c": "dou-paragraph", "t": "- Marcador para quadro branco;"}, {"c": "dou-paragraph", "t": "- Caneta hidrográfica sem tampa respirável, de uso adulto, desde que evidenciado no produto ou na embalagem de forma clara, precisa, ostensiva e em língua portuguesa."}, {"c": "dou-paragraph", "t": "5. Cola sólida, líquida ou gel"}, {"c": "dou-paragraph", "t": "5.1 Escopo:"}, {"c": "dou-paragraph", "t": "Preparado glutinoso sólido, líquido ou gel, denominado cola, para fazer aderir papel ou outras substâncias, sem uso de aquecimento, podendo ser branca, transparente, colorida ou com brilho (exemplos: cola bastão, cola branca, cola em gel, etc.), embalada em frascos com auto aplicador (exemplo: cola líquida), ou em tubos auto aplicadores com tampa e mecanismo helicoidal de elevação (exemplo: cola sólida)."}, {"c": "dou-paragraph", "t": "5.2 Exceções:"}, {"c": "dou-paragraph", "t": "- Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Cola líquida ou sólida destinada a pequenos reparos, do tipo cola tudo, cola madeira, cola tecido, cola vinil, cola cerâmica, cola isopor, cola vidro cola metal e outras dessa categoria;"}, {"c": "dou-paragraph", "t": "- Colas líquidas ou sólidas que sejam aplicadas necessariamente usando aquecimento;"}, {"c": "dou-paragraph", "t": "- Cola em fita;"}, {"c": "dou-paragraph", "t": "- Fita dupla face;"}, {"c": "dou-paragraph", "t": "- Fita adesiva."}, {"c": "dou-paragraph", "t": "6. Corretor de Fita ou Tinta"}, {"c": "dou-paragraph", "t": "6.1 Escopo:"}, {"c": "dou-paragraph", "t": "Corretor em tinta ou fita, aplicado sobre texto escrito que se pretende corrigir, geralmente de cor branca, apresentado em tubo ou caneta (corretor em tinta) ou em dispenser auto aplicador (corretor de fita)."}, {"c": "dou-paragraph", "t": "6.2 Exceção:"}, {"c": "dou-paragraph", "t": "Fita decorativa, apresentada em dispenser auto aplicador."}, {"c": "dou-paragraph", "t": "7. Compasso"}, {"c": "dou-paragraph", "t": "7.1 Escopo:"}, {"c": "dou-paragraph", "t": "Instrumento composto por duas hastes articuladas, que serve para traçar circunferências, arcos de círculo e tomar medidas, que apresente todas as características a seguir:"}, {"c": "dou-paragraph", "t": "- Compasso com capacidade para desenhar círculos de até 320 mm de diâmetro;"}, {"c": "dou-paragraph", "t": "- Compasso com suporte de giro em polímero (resina termoplástica);"}, {"c": "dou-paragraph", "t": "- Compasso de uma ponta seca e outra com grafite ou suporte para lápis."}, {"c": "dou-paragraph", "t": "7.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Compasso com capacidade para desenhar círculos de mais de 320 mm de diâmetro;"}, {"c": "dou-paragraph", "t": "- Compasso de duas pontas secas;"}, {"c": "dou-paragraph", "t": "- Compasso com suporte de giro em material diferente da resina termoplástica;"}, {"c": "dou-paragraph", "t": "- Compasso de ponta de nanquim, giz ou outro material que não seja o grafite."}, {"c": "dou-paragraph", "t": "8. Curva Francesa"}, {"c": "dou-paragraph", "t": "8.1 Escopo:"}, {"c": "dou-paragraph", "t": "Instrumento auxiliar para traçar curvas diversas, manufaturado em polímero (resina termoplástica), de formatos diversos."}, {"c": "dou-paragraph", "t": "8.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Fabricada em madeira, aço, alumínio ou outros materiais diferentes da resina termoplástica;"}, {"c": "dou-paragraph", "t": "- Que apresenta letras e/ou símbolos de engenharia, usados em processo de normografia auxiliar."}, {"c": "dou-paragraph", "t": "9. Esquadro"}, {"c": "dou-paragraph", "t": "9.1 Escopo:"}, {"c": "dou-paragraph", "t": "Instrumento com o qual se traçam ângulos retos e se tiram perpendiculares, geralmente em forma de triângulo retângulo, nos formatos padrão de 45° e 60°, que apresente todas as características a seguir:"}, {"c": "dou-paragraph", "t": "- Esquadro com escalas em centímetros (podendo apresentar escala adicional em outra unidade de medida);"}, {"c": "dou-paragraph", "t": "- Esquadro com hipotenusa de até 40 cm;"}, {"c": "dou-paragraph", "t": "- Esquadro manufaturado em resina termoplástica."}, {"c": "dou-paragraph", "t": "9.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Hipotenusa maior que 40 cm;"}, {"c": "dou-paragraph", "t": "- Fabricado em qualquer material diferente da resina termoplástica."}, {"c": "dou-paragraph", "t": "10. Giz de Cera"}, {"c": "dou-paragraph", "t": "10.1 Escopo:"}, {"c": "dou-paragraph", "t": "Objeto formador de traço em cera para escrita ou desenho, com o corpo em qualquer formato."}, {"c": "dou-paragraph", "t": "10.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Giz para lousa (quadro negro);"}, {"c": "dou-paragraph", "t": "- Giz do tipo risque e apague (ex: giz de cera retrátil para pintar no banho);"}, {"c": "dou-paragraph", "t": "- Giz gel;"}, {"c": "dou-paragraph", "t": "- Giz líquido;"}, {"c": "dou-paragraph", "t": "- Giz marcador de tecidos;"}, {"c": "dou-paragraph", "t": "- Giz aquarelável, solúvel em água."}, {"c": "dou-paragraph", "t": "11. Lápis de Cor"}, {"c": "dou-paragraph", "t": "11.1 Escopo:"}, {"c": "dou-paragraph", "t": "Objeto que envolve uma haste fina de material colorido (mina), e que serve para escrever ou desenhar, sendo lápis inteiro ou meio lápis, com ou sem ponteira de borracha em sua extremidade, aquarelável ou não, apagável ou não."}, {"c": "dou-paragraph", "t": "11.2 Exceções:"}, {"c": "dou-paragraph", "t": "Lápis que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Lápis pastel colorido;"}, {"c": "dou-paragraph", "t": "- Lápis de cor para uso profissional, geralmente apresentando estojos de madeira ou metálicos, que descrito de forma clara, precisa, ostensiva e em língua portuguesa na embalagem."}, {"c": "dou-paragraph", "t": "- Lápis carvão;"}, {"c": "dou-paragraph", "t": "- Lápis negro;"}, {"c": "dou-paragraph", "t": "- Lápis sanguina;"}, {"c": "dou-paragraph", "t": "- Lápis sépia clara e escura;"}, {"c": "dou-paragraph", "t": "- Lápis crayon branco;"}, {"c": "dou-paragraph", "t": "- Lápis de minas multicoloridas;"}, {"c": "dou-paragraph", "t": "- Lápis cosmético (ex.: lápis de olho, lápis sombra, etc);"}, {"c": "dou-paragraph", "t": "- Lápis de carpinteiro;"}, {"c": "dou-paragraph", "t": "- Lápis dermatográfico."}, {"c": "dou-paragraph", "t": "12. Lápis Grafite"}, {"c": "dou-paragraph", "t": "12.1 Escopo:"}, {"c": "dou-paragraph", "t": "Objeto que envolve uma haste fina de grafite (mina) que serve para escrever ou desenhar, sendo lápis inteiro ou meio lápis, com ou sem ponteira de borracha em sua extremidade, graduados em HB, B, 2B também conhecidos como lápis número 2."}, {"c": "dou-paragraph", "t": "12.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Lápis grafite ou preto graduados em 10H, 9H, 8H, 7H, 6H, 5H, 4H, 3H 2H, 3B, 4B, 5B, 6B, 7B, 8B e 9B;"}, {"c": "dou-paragraph", "t": "- Lápis grafite aquareláveis;"}, {"c": "dou-paragraph", "t": "- Lápis grafite ou preto de carpinteiro ou marceneiro."}, {"c": "dou-paragraph", "t": "13. Lapiseira"}, {"c": "dou-paragraph", "t": "13.1 Escopo:"}, {"c": "dou-paragraph", "t": "Objeto usado para escrever ou desenhar, de forma tubular, cilíndrico ou prismático, ao qual se adapta uma mina de grafite ou de cor com diâmetro inferior a 1,6mm, com ou sem ponteira de borracha em sua extremidade, com reservatório e corpo manufaturados em polímero (resina termoplástica)."}, {"c": "dou-paragraph", "t": "13.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Para grafites de diâmetro superior a 1,6 mm;"}, {"c": "dou-paragraph", "t": "- Com reservatório ou corpo manufaturado em qualquer outro material diferente da resina termoplástica."}, {"c": "dou-paragraph", "t": "14. Marca Texto"}, {"c": "dou-paragraph", "t": "14.1 Escopo:"}, {"c": "dou-paragraph", "t": "Espécie de caneta de ponta fibrosa, chanfrada, rígida, apagável ou não, em cores translúcidas, utilizada para destacar textos."}, {"c": "dou-paragraph", "t": "14.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Marca texto em fita translúcida colorida;"}, {"c": "dou-paragraph", "t": "- Marca texto gel;"}, {"c": "dou-paragraph", "t": "- Marcador técnico de ponta única ou ponta dupla diferentes, com escalas de cores, em tons básicos ou secundários, podendo ser miscíveis entre si, que apresente de forma clara, precisa, ostensiva e em língua portuguesa na sua embalagem que o marca texto é destinado a estudos da cor, de uso profissional."}, {"c": "dou-paragraph", "t": "15. Massa Plástica"}, {"c": "dou-paragraph", "t": "15.1 Escopo:"}, {"c": "dou-paragraph", "t": "Massa manufaturada com matéria prima baseada em parafina ou outro plástico, que serve para modelar formas."}, {"c": "dou-paragraph", "t": "15.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Massa para modelar confeccionada em argila;"}, {"c": "dou-paragraph", "t": "- Cerâmica plástica colorida;"}, {"c": "dou-paragraph", "t": "- Massinha de modelar (base amido);"}, {"c": "dou-paragraph", "t": "- Massinha de modelar associada a brinquedos;"}, {"c": "dou-paragraph", "t": "- Massa plástica base parafina de uso artístico ou profissional, desde que apresente especificação de uso de forma clara, precisa, ostensiva e em língua portuguesa na sua embalagem."}, {"c": "dou-paragraph", "t": "16. Normógrafo"}, {"c": "dou-paragraph", "t": "16.1 Escopo:"}, {"c": "dou-paragraph", "t": "Instrumento auxiliar para desenho de caracteres ou formas geométricas, como círculos e polígonos, manufaturado em polímero (resina termoplástica), sendo estreito, chato e de forma retangular, sobre o qual estão vazados ou recortados um conjunto de caracteres e figuras (alfabeto, números, pontuações e/ou figuras geométricas simples), que servem de molde para a elaboração de legendas."}, {"c": "dou-paragraph", "t": "16.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Normógrafos manufaturados em outros materiais diferentes das resinas termoplásticas;"}, {"c": "dou-paragraph", "t": "- Normógrafos de caracteres individuais (um único caractere por chapa) normalmente manufaturados em chapa de aço para marcações industriais de grandes dimensões;"}, {"c": "dou-paragraph", "t": "- Normógrafo de caracteres específicos pertinentes a setores da engenharia, arquitetura e similares, desde que apresente de forma clara, precisa, ostensiva e em língua portuguesa na sua embalagem a especificação de uso artístico ou profissional."}, {"c": "dou-paragraph", "t": "17. Pasta Aba e Elástico"}, {"c": "dou-paragraph", "t": "17.1 Escopo:"}, {"c": "dou-paragraph", "t": "Pasta com aba, geralmente retangular, fabricada em papel cartão ou plástico corrugado ou liso, com elásticos usados para fechar ou abrir a pasta."}, {"c": "dou-paragraph", "t": "17.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Pasta em L;"}, {"c": "dou-paragraph", "t": "- Pasta grampo trilho;"}, {"c": "dou-paragraph", "t": "- Pasta catálogo;"}, {"c": "dou-paragraph", "t": "- Pasta sem aba;"}, {"c": "dou-paragraph", "t": "- Pasta sem elástico;"}, {"c": "dou-paragraph", "t": "- Pastas em material diferente do plástico ou papel cartão."}, {"c": "dou-paragraph", "t": "18. Régua"}, {"c": "dou-paragraph", "t": "18.1 Escopo:"}, {"c": "dou-paragraph", "t": "Instrumento com o qual se traçam linhas retas e se efetuam medições, manufaturado em polímero (resina termoplástica), sendo estreito, chato e de forma retangular, em comprimento máximo de 40 cm, com pelo menos uma escala em unidade de medida SI (exemplo: centímetros)"}, {"c": "dou-paragraph", "t": "18.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Comprimento maior que 40 cm;"}, {"c": "dou-paragraph", "t": "- Manufaturada em materiais diferentes das resinas termoplásticas;"}, {"c": "dou-paragraph", "t": "- Exclusivamente com escala distinta da unidade de medida SI."}, {"c": "dou-paragraph", "t": "19. Tesoura de Ponta Redonda"}, {"c": "dou-paragraph", "t": "19.1 Escopo:"}, {"c": "dou-paragraph", "t": "Instrumento cortante, formado de duas lâminas que se movem em torno de um eixo comum, sendo tesouras infantis (pequenas), com fios que produzem corte reto, de ponta redonda com aplicação de resina termoplástica no cabo ou em toda a estrutura da tesoura, de comprimento da lâmina de corte até 6 cm."}, {"c": "dou-paragraph", "t": "19.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Sem pontas arredondadas;"}, {"c": "dou-paragraph", "t": "- Com fios que produzem cortes decorativos usadas para patchwork e outras técnicas de artesanatos (exemplo: tesoura de picotar, ondulada, zigue zague, etc);"}, {"c": "dou-paragraph", "t": "- Com comprimento de lâmina de corte maior que 6 cm;"}, {"c": "dou-paragraph", "t": "- Sem aplicação de resinas termoplásticas em sua estrutura."}, {"c": "dou-paragraph", "t": "20. Transferidor"}, {"c": "dou-paragraph", "t": "20.1 Escopo:"}, {"c": "dou-paragraph", "t": "Instrumento para marcar e medir ângulos, de formato circular ou semicircular, manufaturado em polímero (resina termoplástica), com escala de até 360° (circular) ou 180° (semicircular) de diâmetros até 20 cm."}, {"c": "dou-paragraph", "t": "20.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Diâmetro maior que 20 cm;"}, {"c": "dou-paragraph", "t": "- Fabricado em qualquer material diferente de resina termoplástica."}, {"c": "dou-paragraph", "t": "21. Tinta (Guache, Plástica, Pintura a Dedo)"}, {"c": "dou-paragraph", "t": "21.1 Escopo:"}, {"c": "dou-paragraph", "t": "Substância líquida ou pastosa, colorida, à base de água, usada para escrever ou desenhar, sendo tinta guache, tinta plástica ou tinta para pintura a dedo."}, {"c": "dou-paragraph", "t": "21.2 Exceções:"}, {"c": "dou-paragraph", "t": "Produto que apresente uma ou mais dentre as seguintes características:"}, {"c": "dou-paragraph", "t": "- Tinta nanquim;"}, {"c": "dou-paragraph", "t": "- Tinta base acrílica;"}, {"c": "dou-paragraph", "t": "- Tinta base óleo;"}, {"c": "dou-paragraph", "t": "- Tinta base solvente;"}, {"c": "dou-paragraph", "t": "- Tinta base resina epóxi;"}, {"c": "dou-paragraph", "t": "- Outras tintas para usos específicos (exemplo: tinta para construção civil, tinta automotiva, tinta verniz, tinta texturizada, tinta PU, tinta para altas temperaturas, etc).\" (NR)"}, {"c": "dou-paragraph", "t": "Art. 3º Esta Portaria entra em vigor na data de sua publicação no Diário Oficial da União."}]});